from collections import Counter

def count_pairs(words):
    pairs = Counter()
    for symbols, frequency in words.items():
        for i in range(len(symbols) - 1):
            pairs[(symbols[i], symbols[i + 1])] += frequency
    return pairs

corpus = {
    ("l", "o", "w"): 5,
    ("l", "o", "w", "e", "r"): 2,
    ("n", "e", "w", "e", "s", "t"): 6
}
print(count_pairs(corpus).most_common())

from collections import Counter

def get_pair_counts(words):
    pairs = Counter()
    for symbols, frequency in words.items():
        for i in range(len(symbols) - 1):
            pairs[(symbols[i], symbols[i + 1])] += frequency
    return pairs

def merge_pair(words, pair):
    merged_words = {}
    merged_symbol = "".join(pair)
    for symbols, frequency in words.items():
        result = []
        i = 0
        while i < len(symbols):
            if i + 1 < len(symbols) and (symbols[i], symbols[i + 1]) == pair:
                result.append(merged_symbol)
                i += 2
            else:
                result.append(symbols[i])
                i += 1
        merged_words[tuple(result)] = merged_words.get(tuple(result), 0) + frequency
    return merged_words

words = {("l", "o", "w"): 5, ("l", "o", "w", "e", "r"): 2}
pair = get_pair_counts(words).most_common(1)[0][0]
print("Selected pair:", pair)
print(merge_pair(words, pair))

